window.addEventListener("load",function(){var images=[];var thumbs=document.querySelectorAll("[thumb-src]");[].forEach.call(thumbs,function(e){var dec=new Decoder;var aspectRatioFiller=e.querySelector("div");aspectRatioFiller.appendChild(dec.tmpCanvas);dec.tmpCanvas.style.width="100%";dec.tmpCanvas.style.height="100%";var lazyLoad=e.getAttribute("thumb-lazy")!==null;var img=new Image;img.onload=function(){dec.decode(img);requestAnimationFrame(function(){dec.tmpCanvas.style.opacity=1});if(!lazyLoad)loadImage(e.getAttribute("original-src"),aspectRatioFiller)};if(lazyLoad)images.push({src:e.getAttribute("original-src"),element:aspectRatioFiller});img.src=e.getAttribute("thumb-src")});function loadImage(src,element){var fullImg=new Image;fullImg.className="final";element.appendChild(fullImg);fullImg.onload=function(){requestAnimationFrame(function(){fullImg.style.opacity=1})};fullImg.src=src}function elementInViewport(el){var rect=el.getBoundingClientRect();var h=window.innerHeight||document.documentElement.clientHeight;return rect.top<=h&&rect.bottom>=0}processScroll=function(){for(var i=images.length-1;i>=0;i--){if(elementInViewport(images[i].element)){loadImage(images[i].src,images[i].element);images.splice(i,1)}}};window.addEventListener("scroll",scrollInvalidate);var timeout=null;function scrollInvalidate(){if(timeout)timeout=clearTimeout(timeout);timeout=setTimeout(processScroll,100)}processScroll()});